css:
.widget-container {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 28px;
  overflow: hidden;
  background: #222;
  box-sizing: border-box;
}

.bg-img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 1;
}

.overlay {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  padding: 20px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: center;
  color: #ffffff;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  text-shadow: 0 4px 12px rgba(0, 0, 0, 0.5), 0 2px 4px rgba(0, 0, 0, 0.4);
}

.date-large {
  font-size: 110px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -4px;
  margin-left: -10px;
}

.info-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  margin-top: -20px;
  padding-right: 10px;
}

.weekday {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 1px;
}

.quote {
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 1px;
  opacity: 0.95;
  margin-top: 6px;
  text-align: right;
  max-width: 160px;
  line-height: 1.4;
}

.time-display {
  position: absolute;
  bottom: 20px;
  left: 20px;
  font-size: 26px;
  font-weight: 600;
  letter-spacing: 1px;
  color: #ffffff;
}

.anniversary-widget {
  width: 100%;
  height: 100%;
  /* 核心修改：透明度从 0.7 降到 0.4 */
  background: rgba(240, 240, 240, 0.4); 
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  border-radius: 28px;
  padding: 16px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #000000;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.06);
}

.main-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  padding: 0 10px;
  box-sizing: border-box;
}

.user-column {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 100px; 
}

.username {
  font-size: 15px;
  font-weight: 600;
  color: #222;
}

.avatar-group {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  width: 100%;
}

.wings {
  font-size: 14px;
  color: #999;
  font-weight: bold;
  flex-shrink: 0; 
}

.avatar-box {
  width: 70px;
  height: 70px;
  flex: 0 0 70px; 
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  overflow: hidden;
  display: flex;
  justify-content: center;
  align-items: center;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.avatar-box img {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
  border: none; 
}

.center-column {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  flex: 1; 
}

.heart-icon {
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  color: #222;
  margin-bottom: 4px;
}

.days {
  font-size: 32px;
  font-weight: 800;
  color: #000;
  line-height: 1.1;
}

.date-display {
  font-size: 13px;
  color: #555;
  margin-top: 2px;
}

.footer-text {
  font-size: 16px;
  font-weight: 600;
  color: #000;
  margin-top: 16px;
  letter-spacing: 0.5px;
}
